:root {
  --ocean-deep: #0a4f6e;
  --ocean-mid: #1a7fa0;
  --ocean-light: #d0eff9;
  --coral: #f4845f;
  --coral-light: #fde8df;
  --sand: #fdf6ec;
  --text-dark: #0d2b38;
  --text-muted: #5a8a9f;
  --white: #ffffff;
  --tag-bg: #e6f7ff;
  --tag-border: #90d4f0;
  --footer-bg: #0d3d54;
}

article.booking-card {
  width: 460px;
  border-radius: 18px;
  overflow: hidden;
  border: 1px solid var(--ocean-mid);
  background: var(--white);
  font-size: 14px;
  color: var(--text-dark);
  margin: 0 auto;
}

.card-header {
  background: var(--ocean-deep);
  padding: 18px 20px 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.tour-badge {
  display: inline-block;
  background: var(--coral);
  color: var(--white);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 3px 10px;
  border-radius: 20px;
  align-self: flex-start;
}

.tour-title {
  font-size: 22px;
  font-weight: 800;
  color: var(--white);
  margin: 0;
  line-height: 1.2;
}

.tour-location {
  font-size: 13px;
  color: var(--ocean-light);
  margin: 0;
}

.card-body {
  background: var(--sand);
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.detail-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.detail-item {
  background: var(--white);
  border: 1px solid var(--tag-border);
  border-radius: 10px;
  padding: 10px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.detail-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.detail-value {
  font-size: 14px;
  font-weight: 700;
  color: var(--ocean-deep);
}

.stops-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.stop-tag {
  background: var(--tag-bg);
  border: 1px solid var(--tag-border);
  border-radius: 20px;
  padding: 5px 12px;
  font-size: 12px;
  font-weight: 600;
  color: var(--ocean-mid);
}

.card-footer {
  background: var(--footer-bg);
  padding: 14px 20px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.guest-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.guest-name {
  font-size: 14px;
  font-weight: 700;
  color: var(--white);
}

.guest-count {
  font-size: 11px;
  color: var(--ocean-light);
}

.price-block {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 1px;
}

.price-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--ocean-light);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.price-amount {
  font-size: 22px;
  font-weight: 800;
  color: var(--coral);
  line-height: 1;
}

.confirm-btn {
  background: var(--coral);
  color: var(--white);
  border: none;
  border-radius: 10px;
  padding: 10px 18px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
}
